1	-- Module: customer/member management. Customers are optional — a
2	-- transaction can be linked to one at checkout to build purchase history,
3	-- but walk-in sales without a customer remain fully supported.
4	
5	create table public.customers (
6	  id uuid primary key default gen_random_uuid(),
7	  business_id uuid not null references public.businesses (id) on delete cascade,
8	  name text not null,
9	  phone text,
10	  email text,
11	  note text,
12	  deleted_at timestamptz,
13	  created_at timestamptz not null default now()
14	);
15	
16	create index customers_business_id_idx on public.customers (business_id);
17	-- Phone only needs to be unique among live (non-deleted) customers of a business.
18	create unique index customers_business_id_phone_key
19	  on public.customers (business_id, phone)
20	  where phone is not null and deleted_at is null;
21	
22	alter table public.customers enable row level security;
23	
24	create policy "Owner manages customers of own businesses"
25	on public.customers for all
26	using (private.owns_business(business_id))
27	with check (private.owns_business(business_id));
28	
29	-- Link transactions to an (optional) customer -----------------------------
30	
31	alter table public.transactions
32	  add column if not exists customer_id uuid references public.customers (id) on delete set null;
33	
34	create index transactions_customer_id_idx on public.transactions (customer_id);
35	
36	-- checkout_transaction now accepts an optional customer to attach ---------
37	
38	drop function if exists public.checkout_transaction(uuid, uuid, jsonb, text, numeric, numeric, text);
39	
40	create or replace function public.checkout_transaction(
41	  p_business_id uuid,
42	  p_cashier_id uuid,
43	  p_items jsonb, -- array of {product_id, qty, disc, disc_type}
44	  p_payment_method text,
45	  p_received numeric default null,
46	  p_order_disc numeric default 0,
47	  p_order_disc_type text default 'pct',
48	  p_customer_id uuid default null
49	)
50	returns table (transaction_id uuid, invoice_number text)
51	language plpgsql
52	security definer
53	set search_path = ''
54	as $$
55	declare
56	  v_business record;
57	  v_invoice_number text;
58	  v_seq int;
59	  v_subtotal_raw numeric(12, 2) := 0;
60	  v_total_item_disc numeric(12, 2) := 0;
61	  v_order_disc_amt numeric(12, 2) := 0;
62	  v_subtotal numeric(12, 2);
63	  v_service numeric(12, 2) := 0;
64	  v_tax numeric(12, 2) := 0;
65	  v_total numeric(12, 2);
66	  v_total_cost numeric(12, 2) := 0;
67	  v_transaction_id uuid;
68	  v_item jsonb;
69	  v_qty numeric(12, 2);
70	  v_product_id uuid;
71	  v_product record;
72	  v_line_gross numeric(12, 2);
73	  v_disc numeric(12, 2);
74	  v_disc_type text;
75	  v_item_disc numeric(12, 2);
76	  v_change numeric(12, 2);
77	  v_shift_id uuid;
78	  v_recipe record;
79	begin
80	  if not private.owns_business(p_business_id) then
81	    raise exception 'not authorized';
82	  end if;
83	
84	  if not exists (
85	    select 1 from public.cashiers c
86	    where c.id = p_cashier_id and c.business_id = p_business_id and c.active
87	  ) then
88	    raise exception 'invalid cashier';
89	  end if;
90	
91	  if p_customer_id is not null and not exists (
92	    select 1 from public.customers c
93	    where c.id = p_customer_id and c.business_id = p_business_id and c.deleted_at is null
94	  ) then
95	    raise exception 'invalid customer';
96	  end if;
97	
98	  if p_payment_method is null or length(trim(p_payment_method)) = 0 then
99	    raise exception 'payment method required';
100	  end if;
101	
102	  if p_items is null or jsonb_array_length(p_items) = 0 then
103	    raise exception 'cart is empty';
104	  end if;
105	
106	  if p_order_disc_type not in ('pct', 'amt') then
107	    raise exception 'invalid order discount type';
108	  end if;
109	
110	  if p_order_disc is null or p_order_disc < 0
111	     or (p_order_disc_type = 'pct' and p_order_disc > 100) then
112	    raise exception 'invalid order discount';
113	  end if;
114	
115	  select b.tax_enabled, b.tax_rate, b.service_enabled, b.service_rate
116	  into v_business
117	  from public.businesses b
118	  where b.id = p_business_id;
119	
120	  select id into v_shift_id
121	  from public.shifts
122	  where business_id = p_business_id and closed_at is null
123	  limit 1;
124	
125	  if v_shift_id is null then
126	    raise exception 'no active shift — open a shift before selling';
127	  end if;
128	
129	  select count(*) + 1 into v_seq
130	  from public.transactions t
131	  where t.business_id = p_business_id
132	    and t.date::date = current_date;
133	
134	  v_invoice_number := 'INV-' || to_char(current_date, 'YYYYMMDD') || '-' || lpad(v_seq::text, 4, '0');
135	
136	  insert into public.transactions (
137	    business_id, shift_id, cashier_id, customer_id, invoice_number, date,
138	    subtotal_raw, subtotal, total, total_cost, gross_profit
139	  ) values (
140	    p_business_id, v_shift_id, p_cashier_id, p_customer_id, v_invoice_number, now(),
141	    0, 0, 0, 0, 0
142	  )
143	  returning id into v_transaction_id;
144	
145	  for v_item in select * from jsonb_array_elements(p_items)
146	  loop
147	    v_product_id := (v_item ->> 'product_id')::uuid;
148	    v_qty := (v_item ->> 'qty')::numeric;
149	    v_disc := coalesce((v_item ->> 'disc')::numeric, 0);
150	    v_disc_type := coalesce(v_item ->> 'disc_type', 'pct');
151	
152	    if v_qty is null or v_qty <= 0 then
153	      raise exception 'invalid quantity';
154	    end if;
155	
156	    if v_disc_type not in ('pct', 'amt') then
157	      raise exception 'invalid item discount type';
158	    end if;
159	
160	    if v_disc < 0 or (v_disc_type = 'pct' and v_disc > 100) then
161	      raise exception 'invalid item discount';
162	    end if;
163	
164	    select * into v_product
165	    from public.products p
166	    where p.id = v_product_id
167	      and p.business_id = p_business_id
168	      and p.deleted_at is null;
169	
170	    if not found then
171	      raise exception 'product not found: %', v_product_id;
172	    end if;
173	
174	    v_line_gross := v_product.price * v_qty;
175	    v_item_disc := case v_disc_type
176	      when 'pct' then round(v_line_gross * v_disc / 100)
177	      else least(v_disc * v_qty, v_line_gross)
178	    end;
179	
180	    insert into public.transaction_items (
181	      transaction_id, product_id, name, category, price, cost, qty, disc, disc_type
182	    ) values (
183	      v_transaction_id, v_product.id, v_product.name, v_product.category,
184	      v_product.price, v_product.cost, v_qty, v_disc, v_disc_type
185	    );
186	
187	    update public.products
188	    set stock = greatest(0, stock - v_qty)
189	    where id = v_product_id;
190	
191	    -- Consume ingredients per the product's recipe (if any).
192	    for v_recipe in
193	      select pr.ingredient_id, pr.qty as recipe_qty
194	      from public.product_recipes pr
195	      where pr.product_id = v_product_id and pr.ingredient_id is not null
196	    loop
197	      insert into public.transaction_ingredient_consumption (
198	        transaction_id, ingredient_id, qty
199	      ) values (
200	        v_transaction_id, v_recipe.ingredient_id, v_recipe.recipe_qty * v_qty
201	      );
202	
203	      update public.ingredients
204	      set stock = greatest(0, stock - (v_recipe.recipe_qty * v_qty))
205	      where id = v_recipe.ingredient_id;
206	    end loop;
207	
208	    v_subtotal_raw := v_subtotal_raw + v_line_gross;
209	    v_total_item_disc := v_total_item_disc + v_item_disc;
210	    v_total_cost := v_total_cost + v_product.cost * v_qty;
211	  end loop;
212	
213	  v_order_disc_amt := case p_order_disc_type
214	    when 'pct' then round((v_subtotal_raw - v_total_item_disc) * p_order_disc / 100)
215	    else least(p_order_disc, v_subtotal_raw - v_total_item_disc)
216	  end;
217	
218	  v_subtotal := v_subtotal_raw - v_total_item_disc - v_order_disc_amt;
219	
220	  if v_business.service_enabled then
221	    v_service := round(v_subtotal * v_business.service_rate / 100);
222	  end if;
223	
224	  if v_business.tax_enabled then
225	    v_tax := round((v_subtotal + v_service) * v_business.tax_rate / 100);
226	  end if;
227	
228	  v_total := v_subtotal + v_service + v_tax;
229	
230	  update public.transactions
231	  set subtotal_raw = v_subtotal_raw,
232	      subtotal = v_subtotal,
233	      total_item_disc = v_total_item_disc,
234	      order_disc_amt = v_order_disc_amt,
235	      service = v_service,
236	      tax = v_tax,
237	      total = v_total,
238	      total_cost = v_total_cost,
239	      gross_profit = v_subtotal - v_total_cost
240	  where id = v_transaction_id;
241	
242	  v_change := greatest(coalesce(p_received, v_total) - v_total, 0);
243	
244	  insert into public.transaction_payments (
245	    transaction_id, method, amount, received, change
246	  ) values (
247	    v_transaction_id, p_payment_method, v_total, p_received, v_change
248	  );
249	
250	  return query select v_transaction_id, v_invoice_number;
251	end;
252	$$;
253	
254	grant execute on function public.checkout_transaction(uuid, uuid, jsonb, text, numeric, numeric, text, uuid) to authenticated;
