1	import { notFound } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	import { getCashierSession } from "@/lib/cashier-session";
4	import PinScreen from "./pin-screen";
5	import OpenShiftScreen from "./open-shift-screen";
6	import PosScreen from "./pos-screen";
7	
8	export default async function PosPage({
9	  params,
10	}: {
11	  params: Promise<{ businessId: string }>;
12	}) {
13	  const { businessId } = await params;
14	  const supabase = await createClient();
15	
16	  const { data: business } = await supabase
17	    .from("businesses")
18	    .select(
19	      "id, name, business_type, tax_enabled, tax_rate, service_enabled, service_rate",
20	    )
21	    .eq("id", businessId)
22	    .single();
23	
24	  if (!business) {
25	    notFound();
26	  }
27	
28	  const session = await getCashierSession(businessId);
29	
30	  if (!session) {
31	    const { data: cashiers } = await supabase
32	      .from("cashiers")
33	      .select("id, name, role")
34	      .eq("business_id", businessId)
35	      .eq("active", true)
36	      .order("created_at", { ascending: true });
37	
38	    return (
39	      <PinScreen
40	        businessId={businessId}
41	        businessName={business.name}
42	        cashiers={cashiers ?? []}
43	      />
44	    );
45	  }
46	
47	  const { data: activeShift } = await supabase
48	    .from("shifts")
49	    .select("id, opening_cash, opened_at")
50	    .eq("business_id", businessId)
51	    .is("closed_at", null)
52	    .maybeSingle();
53	
54	  if (!activeShift) {
55	    return (
56	      <OpenShiftScreen
57	        businessId={businessId}
58	        businessName={business.name}
59	        cashierId={session.cashierId}
60	        cashierName={session.name}
61	      />
62	    );
63	  }
64	
65	  const { data: products } = await supabase
66	    .from("products")
67	    .select("id, name, category, price, cost, stock, emoji")
68	    .eq("business_id", businessId)
69	    .is("deleted_at", null)
70	    .order("name", { ascending: true });
71	
72	  const isFnb = business.business_type === "fnb";
73	
74	  const { data: openBillRows } = await supabase
75	    .from("open_bills")
76	    .select("id, label, items, updated_at")
77	    .eq("business_id", businessId)
78	    .order("updated_at", { ascending: false });
79	
80	  const { data: customers } = await supabase
81	    .from("customers")
82	    .select("id, name, phone")
83	    .eq("business_id", businessId)
84	    .is("deleted_at", null)
85	    .order("name", { ascending: true });
86	
87	  const { data: customPaymentMethodRows } = await supabase
88	    .from("custom_payment_methods")
89	    .select("name")
90	    .eq("business_id", businessId)
91	    .order("name", { ascending: true });
92	
93	  let selfOrders: SelfOrderRow[] = [];
94	  if (isFnb) {
95	    const { data: orderRows } = await supabase
96	      .from("self_orders")
97	      .select(
98	        "id, status, created_at, tables(name), self_order_items(product_id, name, qty, price, note)",
99	      )
100	      .eq("business_id", businessId)
101	      .neq("status", "selesai")
102	      .order("created_at", { ascending: true });
103	    selfOrders = (orderRows ?? []) as unknown as SelfOrderRow[];
104	  }
105	
106	  return (
107	    <PosScreen
108	      businessId={businessId}
109	      businessName={business.name}
110	      cashierId={session.cashierId}
111	      cashierName={session.name}
112	      shiftId={activeShift.id}
113	      products={products ?? []}
114	      taxRate={business.tax_enabled ? Number(business.tax_rate) : 0}
115	      serviceRate={business.service_enabled ? Number(business.service_rate) : 0}
116	      openBills={(openBillRows ?? []) as unknown as OpenBillRow[]}
117	      customers={customers ?? []}
118	      isFnb={isFnb}
119	      customPaymentMethods={(customPaymentMethodRows ?? []).map((m) => m.name)}
120	      selfOrders={selfOrders.map((o) => ({
121	        id: o.id,
122	        status: o.status,
123	        createdAt: o.created_at,
124	        tableName: o.tables?.name ?? "Meja terhapus",
125	        items: o.self_order_items.map((i) => ({
126	          productId: i.product_id,
127	          name: i.name,
128	          qty: i.qty,
129	          price: i.price,
130	          note: i.note,
131	        })),
132	      }))}
133	    />
134	  );
135	}
136	
137	type OpenBillRow = {
138	  id: string;
139	  label: string;
140	  updated_at: string;
141	  items: {
142	    product_id: string;
143	    name: string;
144	    price: number;
145	    qty: number;
146	    disc: number;
147	    disc_type: "pct" | "amt";
148	  }[];
149	};
150	
151	type SelfOrderRow = {
152	  id: string;
153	  status: "baru" | "diproses";
154	  created_at: string;
155	  tables: { name: string } | null;
156	  self_order_items: {
157	    product_id: string | null;
158	    name: string;
159	    qty: number;
160	    price: number;
161	    note: string | null;
162	  }[];
163	};
164

1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { usePathname } from "next/navigation";
6	import LogoutButton from "@/app/dashboard/logout-button";
7	
8	type NavItem = { href: string; label: string; icon: string };
9	type NavGroup = { title: string; items: NavItem[] };
10	
11	function buildNavGroups(businessId: string, isFnb: boolean): NavGroup[] {
12	  const base = `/business/${businessId}`;
13	  return [
14	    {
15	      title: "Keuangan",
16	      items: [
17	        { href: base, label: "Dashboard", icon: "📊" },
18	        { href: `${base}/reports`, label: "Laporan", icon: "📈" },
19	        { href: `${base}/reports/laba-rugi`, label: "Laba Rugi", icon: "🧮" },
20	        { href: `${base}/finance`, label: "Keuangan", icon: "💰" },
21	        { href: `${base}/transactions`, label: "Riwayat Transaksi", icon: "🧾" },
22	        { href: `${base}/shifts`, label: "Riwayat Shift", icon: "⏱️" },
23	      ],
24	    },
25	    {
26	      title: "Operasional",
27	      items: [
28	        { href: `${base}/products`, label: "Kelola Produk", icon: "📦" },
29	        ...(isFnb
30	          ? [
31	              { href: `${base}/ingredients`, label: "Bahan Baku", icon: "🧂" },
32	              { href: `${base}/tables`, label: "Meja & Self-Order", icon: "🪑" },
33	            ]
34	          : []),
35	        { href: `${base}/customers`, label: "Pelanggan", icon: "👥" },
36	      ],
37	    },
38	    {
39	      title: "SDM",
40	      items: [
41	        { href: `${base}/cashiers`, label: "Kelola Kasir", icon: "🧑‍💼" },
42	        { href: `${base}/attendance`, label: "Absensi", icon: "📅" },
43	        { href: `${base}/payroll`, label: "Payroll", icon: "💵" },
44	      ],
45	    },
46	    {
47	      title: "Lainnya",
48	      items: [
49	        { href: `${base}/settings`, label: "Pengaturan", icon: "🔧" },
50	        { href: `${base}/activity`, label: "Aktivitas", icon: "⚙️" },
51	      ],
52	    },
53	  ];
54	}
55	
56	function useActiveHref(groups: NavGroup[], pathname: string): string | null {
57	  const allHrefs = groups.flatMap((g) => g.items.map((i) => i.href));
58	  const matches = allHrefs.filter((h) => pathname === h || pathname.startsWith(`${h}/`));
59	  if (matches.length === 0) return null;
60	  return matches.sort((a, b) => b.length - a.length)[0];
61	}
62	
63	function SidebarContent({
64	  businessId,
65	  businessName,
66	  isFnb,
67	  pathname,
68	  onNavigate,
69	  showLogout = true,
70	}: {
71	  businessId: string;
72	  businessName: string;
73	  isFnb: boolean;
74	  pathname: string;
75	  onNavigate?: () => void;
76	  showLogout?: boolean;
77	}) {
78	  const groups = buildNavGroups(businessId, isFnb);
79	  const activeHref = useActiveHref(groups, pathname);
80	
81	  return (
82	    <div className="flex h-full flex-col">
83	      <div className="flex items-center gap-2.5 border-b border-zinc-100 px-5 py-5">
84	        <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-600">
85	          <span className="text-sm font-bold text-white">K</span>
86	        </div>
87	        <div className="min-w-0">
88	          <p className="truncate text-sm font-bold text-zinc-900">{businessName}</p>
89	          <p className="text-[11px] text-zinc-400">
90	            {isFnb ? "Restoran / Kafe / F&B" : "Retail / Toko"}
91	          </p>
92	        </div>
93	      </div>
94	
95	      <div className="px-3 pt-4">
96	        <Link
97	          href={`/business/${businessId}/pos`}
98	          onClick={onNavigate}
99	          className="flex items-center justify-center gap-1.5 rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700"
100	        >
101	          🛎️ Buka Kasir
102	        </Link>
103	      </div>
104	
105	      <nav className="flex-1 space-y-5 overflow-y-auto px-3 py-4">
106	        {groups.map((group) => (
107	          <div key={group.title}>
108	            <p className="mb-1.5 px-2 text-[10.5px] font-semibold uppercase tracking-wide text-zinc-400">
109	              {group.title}
110	            </p>
111	            <div className="space-y-0.5">
112	              {group.items.map((item) => (
113	                <Link
114	                  key={item.href}
115	                  href={item.href}
116	                  onClick={onNavigate}
117	                  className={`flex items-center gap-2.5 rounded-lg px-2.5 py-2 text-[13px] font-medium transition-colors ${
118	                    activeHref === item.href
119	                      ? "bg-brand-50 text-brand-700"
120	                      : "text-zinc-600 hover:bg-zinc-50"
121	                  }`}
122	                >
123	                  <span className="text-base leading-none">{item.icon}</span>
124	                  {item.label}
125	                </Link>
126	              ))}
127	            </div>
128	          </div>
129	        ))}
130	      </nav>
131	
132	      <div className="border-t border-zinc-100 px-3 py-3">
133	        <Link
134	          href="/dashboard"
135	          onClick={onNavigate}
136	          className="mb-1 block rounded-lg px-2.5 py-2 text-[13px] font-medium text-zinc-500 hover:bg-zinc-50"
137	        >
138	          ← Semua Toko
139	        </Link>
140	        {showLogout && <LogoutButton />}
141	      </div>
142	    </div>
143	  );
144	}
145	
146	function Topbar({ businessName, userEmail }: { businessName: string; userEmail: string }) {
147	  const today = new Date().toLocaleDateString("id-ID", {
148	    weekday: "long",
149	    day: "numeric",
150	    month: "long",
151	    year: "numeric",
152	  });
153	  const initial = (userEmail || businessName).charAt(0).toUpperCase();
154	
155	  return (
156	    <div className="sticky top-0 z-10 hidden items-center justify-between border-b border-zinc-200 bg-white px-8 py-4 md:flex print:hidden">
157	      <p className="text-sm text-zinc-500">{today}</p>
158	      <div className="flex items-center gap-3">
159	        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-brand-100 text-xs font-bold text-brand-700">
160	          {initial}
161	        </div>
162	        {userEmail && <p className="max-w-[180px] truncate text-sm text-zinc-600">{userEmail}</p>}
163	        <LogoutButton variant="inline" />
164	      </div>
165	    </div>
166	  );
167	}
168	
169	export default function DashboardShell({
170	  businessId,
171	  businessName,
172	  isFnb,
173	  userEmail,
174	  children,
175	}: {
176	  businessId: string;
177	  businessName: string;
178	  isFnb: boolean;
179	  userEmail: string;
180	  children: React.ReactNode;
181	}) {
182	  const pathname = usePathname();
183	  const [mobileNavOpen, setMobileNavOpen] = useState(false);
184	
185	  return (
