66	type CheckoutRpcRow = { transaction_id: string; invoice_number: string };
67	
68	export async function checkout(
69	  businessId: string,
70	  cashierId: string,
71	  items: CartItemInput[],
72	  paymentMethod: string,
73	  received: number | null,
74	  orderDisc: number,
75	  orderDiscType: DiscountType,
76	  customerId: string | null = null,
77	): Promise<CheckoutResult> {
78	  if (items.length === 0) {
79	    return { success: false, error: "Keranjang masih kosong." };
80	  }
81	
82	  const supabase = await createClient();
83	  const { data, error } = await supabase
84	    .rpc("checkout_transaction", {
85	      p_business_id: businessId,
86	      p_cashier_id: cashierId,
87	      p_items: items.map((i) => ({
88	        product_id: i.productId,
89	        qty: i.qty,
90	        disc: i.disc,
91	        disc_type: i.discType,
92	      })),
93	      p_payment_method: paymentMethod,
94	      p_received: received,
95	      p_order_disc: orderDisc,
96	      p_order_disc_type: orderDiscType,
97	      p_customer_id: customerId,
98	    })
99	    .single();
100	
101	  if (error || !data) {
102	    return { success: false, error: error?.message ?? "Gagal memproses transaksi." };
103	  }
104	
105	  const result = data as CheckoutRpcRow;
106	  const itemCount = items.reduce((sum, i) => sum + i.qty, 0);
107	  await logActivity(
108	    supabase,
109	    businessId,
110	    "transaksi",
111	    "sukses",
112	    `Transaksi ${result.invoice_number}`,
113	    `${itemCount} item · ${paymentMethod}`,
114	  );
115	
116	  await printKitchenTicketsForItems(
117	    supabase,
118	    businessId,
119	    "Kasir",
120	    result.invoice_number,
121	    items.map((i) => ({ productId: i.productId, qty: i.qty })),
122	  );
123	
124	  return { success: true, invoiceNumber: result.invoice_number, transactionId: result.transaction_id };
125	}
