127	async function printKitchenTicketsForItems(
128	  supabase: Awaited<ReturnType<typeof createClient>>,
129	  businessId: string,
130	  source: string,
131	  label: string,
132	  items: { productId: string; qty: number; note?: string | null }[],
133	) {
134	  const productIds = Array.from(new Set(items.map((i) => i.productId)));
135	  const { data: products } = await supabase
136	    .from("products")
137	    .select("id, name, category")
138	    .in("id", productIds);
139	  const productMap = new Map((products ?? []).map((p) => [p.id, p]));
140	
141	  const failures = await dispatchKitchenPrint(supabase, businessId, {
142	    source,
143	    label,
144	    items: items.map((i) => ({
145	      name: productMap.get(i.productId)?.name ?? "Item",
146	      category: productMap.get(i.productId)?.category ?? null,
147	      qty: i.qty,
148	      note: i.note,
149	    })),
150	  }).catch(() => []);
151	
152	  const failed = failures.filter((f) => !f.ok);
153	  if (failed.length > 0) {
154	    await logActivity(
155	      supabase,
156	      businessId,
157	      "sistem",
158	      "warning",
159	      `Gagal cetak ke dapur: ${failed.map((f) => f.printer).join(", ")}`,
160	      failed.map((f) => f.error).join(" · "),
161	    );
162	  }
163	}
